def load() -> pd.DataFrame:
    df = pd.read_csv('data/astronomy/input/SILSO/SN_y_tot_V2.0.csv', sep=';', header=None)
    return df

def process(extract_extrema) -> pd.DataFrame:
    maxima = extract_extrema[extract_extrema['type'] == 'maxima'].sort_values('year')

    # Calculate periods between consecutive maxima
    years = maxima['year'].values
    periods = []
    for i in range(len(years) - 1):
        period = years[i + 1] - years[i]
        periods.append(period)

    avg_period = sum(periods) / len(periods) if periods else 0

    result_data = {
        'metric': ['average_period', 'num_periods_calculated'],
        'value': [round(avg_period, 1), len(periods)]
    }

    return pd.DataFrame(result_data)
